function main(): void {
  console.log(new Intl.NumberFormat("de").format(1234567.891), new Intl.NumberFormat("hi").format(5));
  console.log(new Intl.NumberFormat("en-US", { style: "unit", unit: "kilometer-per-hour" }).format(5), new Intl.NumberFormat("en-US", { style: "unit", unit: "liter", unitDisplay: "long" }).format(5), new Intl.NumberFormat().format(Infinity));
  console.log(new Intl.NumberFormat("en-US", { style: "unit", unit: "celsius" }).format(21.5), new Intl.NumberFormat("en-US", { style: "unit", unit: "kilometer-per-hour", unitDisplay: "long" }).format(1), new Intl.NumberFormat("en-US", { style: "unit", unit: "megabyte", unitDisplay: "narrow" }).format(3));
  console.log(new Intl.NumberFormat("en-US").format(-Infinity), new Intl.NumberFormat("en-US", { style: "percent" }).format(Infinity), new Intl.NumberFormat("en-US").format(NaN));
  console.log(JSON.stringify(new Intl.NumberFormat("en-US").formatToParts(Infinity)));
}
